import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';

class BasicImageExample extends StatelessWidget {
  const BasicImageExample({super.key});

  final String validImageUrl = 'https://picsum.photos/300/200';
  final String invalidImageUrl = 'https://notAvalid.uri';

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Cached Image 기본 예제')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            // 1. 기본 사용법 (로딩 및 에러 처리 포함)
            CachedNetworkImage(
              width: 300,
              height: 200,
              fit: BoxFit.cover,
              imageUrl: validImageUrl,
              placeholder: (context, url) => const Center(
                child: CircularProgressIndicator(),
              ), // 로딩 중 표시
              errorWidget: (context, url, error) => const Icon(
                Icons.broken_image,
                size: 50,
                color: Colors.red,
              ), // 에러 발생 시 표시
            ),
            const SizedBox(height: 20),
            // 2. 에러 테스트
            CachedNetworkImage(
              width: 300,
              height: 200,
              imageUrl: invalidImageUrl,
              placeholder: (context, url) => const Text('에러 테스트 중...'),
              errorWidget: (context, url, error) => const Text('이미지 로드 실패!'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';

class AdvancedImageExample extends StatelessWidget {
  const AdvancedImageExample({super.key});

  final String profileUrl = 'https://picsum.photos/id/237/200/200';

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 1. 원형 아바타 구현 (imageBuilder 사용)
        CachedNetworkImage(
          imageUrl: profileUrl,
          placeholder: (context, url) => const CircleAvatar(
            backgroundColor: Colors.grey,
            radius: 50,
          ),
          imageBuilder: (context, imageProvider) => CircleAvatar(
            backgroundImage: imageProvider, // ImageProvider를 직접 사용
            radius: 50,
          ),
        ),
        const SizedBox(height: 20),
        // 2. 진행률 표시 및 커스텀 BoxDecoration
        SizedBox(
          width: 300,
          height: 150,
          child: CachedNetworkImage(
            imageUrl: 'https://picsum.photos/300/150',
            progressIndicatorBuilder: (context, url, downloadProgress) => Center(
              child: CircularProgressIndicator(
                value: downloadProgress.progress, // 0.0 ~ 1.0 사이의 값
              ),
            ),
            imageBuilder: (context, imageProvider) => Container(
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(10),
                image: DecorationImage(
                  image: imageProvider,
                  fit: BoxFit.cover,
                  // 예: 이미지에 색상 필터 적용
                  colorFilter: const ColorFilter.mode(
                    Colors.blueGrey,
                    BlendMode.colorBurn,
                  ),
                ),
              ),
            ),
            fadeInDuration: const Duration(milliseconds: 500), // 페이드인 효과
          ),
        ),
      ],
    );
  }
}

import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';

class OptimizedListView extends StatelessWidget {
  const OptimizedListView({super.key});

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      itemCount: 50,
      itemBuilder: (context, index) {
        // 1. 리스트뷰 내에서 사용: 스크롤 시 이미지가 빠르게 로드됨 (캐싱 덕분)
        return Card(
          child: ListTile(
            leading: SizedBox(
              width: 50,
              height: 50,
              child: CachedNetworkImage(
                // lock=$index를 사용하여 고유한 이미지를 요청 (loremflickr)
                imageUrl: 'https://loremflickr.com/100/100/abstract?lock=$index',
                placeholder: (context, url) => const Icon(Icons.photo),
                errorWidget: (context, url, error) => const Icon(Icons.error),
                // 2. 캐시 크기 제한 (선택 사항)
                maxHeightDiskCache: 100, // 디스크에 저장될 최대 높이 (픽셀)
                maxWidthDiskCache: 100, // 디스크에 저장될 최대 너비 (픽셀)
              ),
            ),
            title: Text('Item $index'),
            subtitle: const Text('Cached image loaded'),
          ),
        );
      },
    );
  }
}

