Widget _errorHandlingImage() {
  return CachedNetworkImage(
    imageUrl: 'http://nonexistent.domain/image.jpg',
    placeholder: (context, url) => const CircularProgressIndicator(),
    errorWidget: (context, url, error) => const Icon(Icons.wifi_off),
    // [2] 상세 에러 리스너 구현
    errorListener: (e) {
      if (e is SocketException) {
        // 네트워크 연결 문제 처리
        print('네트워크 연결 오류: ${e.message}');
      } else {
        // 기타 이미지 로드 예외 처리
        print('이미지 로드 중 알 수 없는 예외 발생: ${e.runtimeType}');
      }
    },
  );
}

// [3] 캐시 수동 제어 함수 예시
Future<void> clearAllCache() async {
  await DefaultCacheManager().emptyCache();
  print('모든 캐시가 삭제되었습니다.');
}
